# Build the SPA, then serve it from nginx running as an unprivileged user.
FROM node:24.21.0-alpine3.24 AS build
WORKDIR /app
COPY package.json package-lock.json ./
RUN npm ci
COPY . .
RUN npm run build

# Listens on 8080 and runs as uid 101: https://github.com/nginx/docker-nginx-unprivileged
FROM nginxinc/nginx-unprivileged:1.30.6-alpine3.24
# Replaces the main config, because worker_processes is only valid there, not in a conf.d include.
COPY nginx.conf /etc/nginx/nginx.conf
# The entrypoint fills this in at start, into /tmp, the one folder the read-only container can write:
# the DNS server from /etc/resolv.conf, and API_HOST. https://github.com/nginx/docker-nginx/tree/master/entrypoint
COPY nginx-upstream.conf.template /etc/nginx/templates/upstream.conf.template
ENV NGINX_ENTRYPOINT_LOCAL_RESOLVERS=1 NGINX_ENVSUBST_OUTPUT_DIR=/tmp API_HOST=api
COPY --from=build /app/dist /usr/share/nginx/html
EXPOSE 8080
    client_body_temp_path /tmp/client_temp;
    proxy_temp_path /tmp/proxy_temp;
    fastcgi_temp_path /tmp/fastcgi_temp;
    uwsgi_temp_path /tmp/uwsgi_temp;
    scgi_temp_path /tmp/scgi_temp;

    gzip on;
    gzip_types text/css application/javascript text/javascript application/json;

    # Pass on the caller's request id, or make one, so nginx and the API log the same id.
    map $http_x_request_id $req_id {
        default $http_x_request_id;
        "" $request_id;
    }

    # Swagger UI at /api/docs loads its script and stylesheet from jsDelivr, its icon from fastapi.tiangolo.com,
    # and starts from one inline script allowed by its hash; the hash changes when FastAPI changes that script.
    map $uri $csp {
        default "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'";
        /api/docs "default-src 'self'; script-src 'self' https://cdn.jsdelivr.net 'sha256-eV3QMumkWxytVHa/LDvu+mnW+PcSAEI4SfFu0iIlbDc='; style-src 'self' https://cdn.jsdelivr.net; img-src 'self' data: https://fastapi.tiangolo.com; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'";
    }

    # The resolver and the API upstream, written by the entrypoint from nginx-upstream.conf.template.
    include /tmp/upstream.conf;

    server {
      58 CLAUDE.md
10:const BASE_URL = __ENV.BASE_URL || "http://web:8080";
11:const APP_ORIGIN = __ENV.APP_ORIGIN || "http://localhost:8080";
16:const API = `${BASE_URL}/api/v1`;

